import React, { useState, useMemo } from 'react';
import { Row, Col, Select, Input, Typography, Empty, Modal, Descriptions, Rate, Tag, Button, message, Divider } from 'antd';
import { PlusOutlined } from '@ant-design/icons';
import TheDiemDen from '../components/TheDiemDen';
import { DiemDen } from '../types/DuLich';

const { Title,Text} = Typography;

interface TrangChuProps {
  onThemDiem: (item: DiemDen) => void;
}

const TrangChu: React.FC<TrangChuProps> = ({ onThemDiem }) => {
  const [tuKhoa, setTuKhoa] = useState('');
  const [loaiHinh, setLoaiHinh] = useState<string | undefined>(undefined);
  const [sapXep, setSapXep] = useState<string | undefined>(undefined);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDiemDen, setSelectedDiemDen] = useState<DiemDen | null>(null);

  const danhSachDiemDen: DiemDen[] = [
    {
      id: '1',
      ten: 'Đà Nẵng',
      diaDiem: 'Miền Trung',
      loaiHinh: 'bien',
      giaThamKhao: 3000000,
      danhGia: 5,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa: 'Cầu Vàng và biển Mỹ Khê xinh đẹp',
      phiAnUong: 1000000, phiDiChuyen: 1000000, phiLuuTru: 1000000
    },
    {
      id: '2',
      ten: 'Đà Lạt',
      diaDiem: 'Lâm Đồng',
      loaiHinh: 'nui',
      giaThamKhao: 2500000,
      danhGia: 4,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa:'Thành phố mơ mộng',
      phiAnUong: 800000, phiDiChuyen: 700000, phiLuuTru: 1000000
    },
    {
      id: '3',
      ten: 'Hạ Long',
      diaDiem: 'Quảng Ninh',
      loaiHinh: 'bien',
      giaThamKhao: 4500000,
      danhGia: 5,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa: 'Kỳ quan thiên nhiên thế giới',
      phiAnUong: 1500000, phiDiChuyen: 1000000, phiLuuTru: 2000000
    },
    {
      id: '4',
      ten: 'Sapa',
      diaDiem: 'Lào Cai',
      loaiHinh: 'nui',
      giaThamKhao: 2800000,
      danhGia: 4.5,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa: 'Đỉnh Fansipan và ruộng bậc thang',
      phiAnUong: 800000, phiDiChuyen: 800000, phiLuuTru: 1200000
    },
    {
      id: '5',
      ten: 'Phú Quốc',
      diaDiem: 'Kiên Giang',
      loaiHinh: 'bien',
      giaThamKhao: 5500000,
      danhGia: 5,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa:'Đảo ngọc với bãi biển xanh trong',
      phiAnUong: 1500000, phiDiChuyen: 2000000, phiLuuTru: 2000000
    },
    {
      id: '6',
      ten: 'Hà Nội',
      diaDiem: 'Thủ đô',
      loaiHinh: 'thanhpho',
      giaThamKhao: 2000000,
      danhGia: 4.2,
      hinhAnh: 'data:image/jpeg;base64,',
      moTa: 'Thành phố ngàn năm văn hiến',
      phiAnUong: 1000000, phiDiChuyen: 300000, phiLuuTru: 700000
    }
  ];
  const handleOpenDetail = (item: DiemDen) => {
    setSelectedDiemDen(item);
    setIsModalOpen(true);
  };

  const duLieuLoc = useMemo(() => {
    let ketQua = danhSachDiemDen.filter(item => 
      item.ten.toLowerCase().includes(tuKhoa.toLowerCase())
    );
    if (loaiHinh) ketQua = ketQua.filter(item => item.loaiHinh === loaiHinh);
    if (sapXep === 'gia-tang') ketQua.sort((a, b) => a.giaThamKhao - b.giaThamKhao);
    else if (sapXep === 'gia-giam') ketQua.sort((a, b) => b.giaThamKhao - a.giaThamKhao);
    return ketQua;
  }, [tuKhoa, loaiHinh, sapXep]);

  return (
    <div>
      <Title level={3} style={{ marginBottom: 24 }}>Khám phá điểm đến nổi bật</Title>
      
      <Row gutter={[16, 16]} style={{ marginBottom: 32 }}>
        <Col xs={24} md={8}>
          <Input placeholder="Tìm theo tên..." onChange={(e) => setTuKhoa(e.target.value)} allowClear />
        </Col>
        <Col xs={12} md={5}>
          <Select placeholder="Loại hình" style={{ width: '100%' }} allowClear onChange={setLoaiHinh}>
            <Select.Option value="bien">Biển</Select.Option>
            <Select.Option value="nui">Núi</Select.Option>
          </Select>
        </Col>
      </Row>

      {duLieuLoc.length > 0 ? (
        <Row gutter={[24, 24]}>
          {duLieuLoc.map((item) => (
            <Col xs={24} sm={12} lg={8} key={item.id}>
              {/* Thẻ hiển thị điểm đến */}
              <TheDiemDen duLieu={item} onXemChiTiet={handleOpenDetail} onThemDiem={onThemDiem} />
              
            </Col>
          ))}
        </Row>
      ) : (
        <Empty description="Không tìm thấy điểm đến" />
      )}

      {/* Modal chi tiết khi nhấn vào ảnh */}
      {/* Tìm đến đoạn <Modal ... > trong file TrangChu.tsx và thay thế phần nội dung bên trong */}
<Modal
  title={
    <Title level={4} style={{ color: '#1890ff', margin: 0 }}>
      {selectedDiemDen?.ten}
    </Title>
  }
  visible={isModalOpen}
  onCancel={() => setIsModalOpen(false)}
  footer={null}
  width={800}
>
  {selectedDiemDen && (
    <div style={{ padding: '10px 0' }}>
      <img 
        src={selectedDiemDen.hinhAnh} 
        alt={selectedDiemDen.ten}
        style={{ width: '100%', height: 350, objectFit: 'cover', borderRadius: 12, marginBottom: 24, boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} 
      />
      
      <Descriptions bordered column={2} labelStyle={{ fontWeight: 'bold', background: '#fafafa' }}>
        <Descriptions.Item label="Vùng miền" span={1}>
          {selectedDiemDen.diaDiem}
        </Descriptions.Item>
        <Descriptions.Item label="Loại hình" span={1}>
          <Tag color="cyan">{selectedDiemDen.loaiHinh === 'bien' ? 'Du lịch Biển' : 'Du lịch Núi'}</Tag>
        </Descriptions.Item>
        <Descriptions.Item label="Đánh giá khách hàng" span={2}>
          <Rate disabled defaultValue={selectedDiemDen.danhGia} /> 
          <span style={{ marginLeft: 8, color: '#faad14' }}>({selectedDiemDen.danhGia}/5)</span>
        </Descriptions.Item>
        <Descriptions.Item label="Giới thiệu chi tiết" span={2}>
          <Text style={{ textAlign: 'justify', display: 'block' }}>
            {selectedDiemDen.moTa} - Đây là điểm đến lý tưởng cho những ai yêu thích khám phá vẻ đẹp thiên nhiên và văn hóa bản địa.
          </Text>
        </Descriptions.Item>
        
        {/* Phần phân bổ ngân sách chi tiết */}
        <Descriptions.Item label="Phân bổ ngân sách" span={2}>
          <div style={{ padding: '10px 0' }}>
            <p>🍴 Ăn uống: <Text strong>{selectedDiemDen.phiAnUong.toLocaleString()} VNĐ</Text></p>
            <p>🚗 Di chuyển: <Text strong>{selectedDiemDen.phiDiChuyen.toLocaleString()} VNĐ</Text></p>
            <p>🏨 Lưu trú: <Text strong>{selectedDiemDen.phiLuuTru.toLocaleString()} VNĐ</Text></p>
            <Divider style={{ margin: '12px 0' }} />
            <p style={{ fontSize: 18 }}>
              <Text strong type="danger">TỔNG CHI PHÍ: </Text>
              <Text strong type="danger" style={{ fontSize: 20 }}>
                {(selectedDiemDen.phiAnUong + selectedDiemDen.phiDiChuyen + selectedDiemDen.phiLuuTru).toLocaleString()} VNĐ
              </Text>
            </p>
          </div>
        </Descriptions.Item>
      </Descriptions>
      
      <div style={{ marginTop: 24, textAlign: 'right' }}>
        <Button size="large" onClick={() => setIsModalOpen(false)} style={{ marginRight: 12 }}>
          Đóng
        </Button>
        <Button 
          type="primary" 
          danger 
          size="large" 
          icon={<PlusOutlined />}
          onClick={() => {
            onThemDiem(selectedDiemDen);
            setIsModalOpen(false);
            message.success(`Đã thêm ${selectedDiemDen.ten} vào lịch trình!`);
          }}
        >
          Thêm ngay vào lịch trình
        </Button>
      </div>
    </div>
  )}
</Modal>
    </div>
  );
};

export default TrangChu;